
(()=>{
 const safeRead=()=>{try{return JSON.parse(sessionStorage.getItem('xmesh-role-preview-v1')||'null')}catch{return null}};
 const initial={agent:{enabled:true,settings:{cwd:'/workspace',allow:'/workspace\n/Users/demo/Projects',deny:'~/.ssh\n~/.aws',exec:'4',pty:'8'}},gateway:{enabled:true,settings:{listen:'127.0.0.1:8080',transport:'HTTP',auth:'PAT'}},ingress:{enabled:false,settings:{listen:'tunnel',issuer:'',domain:'',tls:'autocert'}}};
 let roles=safeRead()||initial,activeRole=null,roleTab='main',draft=null,pending=null,dirty=false,returnFocus=null;
 const names={agent:'Agent',gateway:'Gateway',ingress:'Ingress'};
 const descriptions={agent:'在本机执行工具与管理工作空间',gateway:'连接客户端并路由工具调用',ingress:'通过公网提供受控的访问入口'};
 const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const save=()=>{try{sessionStorage.setItem('xmesh-role-preview-v1',JSON.stringify(roles))}catch{}};
 const status=key=>roles[key].enabled?'已开启':'已关闭';
 const host=document.querySelector('.roles');host.classList.add('role-controls');host.setAttribute('aria-label','角色管理');
 const pop=document.createElement('div');pop.className='role-popover';pop.hidden=true;pop.setAttribute('role','menu');document.body.append(pop);
 const dialog=document.createElement('dialog');dialog.id='role-settings-dialog';dialog.setAttribute('aria-labelledby','role-panel-title');document.body.append(dialog);
 function renderButtons(){host.innerHTML=Object.keys(names).map(key=>`<button type="button" class="role-trigger ${roles[key].enabled?'enabled':''}" data-role-trigger="${key}" aria-haspopup="menu" aria-expanded="false" aria-label="${names[key]} · ${status(key)}"><i></i><span>${names[key]}</span>${icon('chevron')}</button>`).join('')}
 function closePop(){pop.hidden=true;host.querySelectorAll('button').forEach(b=>b.setAttribute('aria-expanded','false'))}
 function positionPop(button){const r=button.getBoundingClientRect();const width=Math.min(274,innerWidth-24);pop.style.width=width+'px';pop.style.left=Math.max(12,Math.min(r.right-width,innerWidth-width-12))+'px';pop.style.top=Math.min(r.bottom+9,innerHeight-240)+'px'}
 function openPop(key,button){const already=!pop.hidden&&activeRole===key;closePop();if(already)return;activeRole=key;returnFocus=button;const last=roles[key].enabled&&Object.values(roles).filter(v=>v.enabled).length===1;pop.innerHTML=`<div class="role-pop-head"><strong>${names[key]}</strong><span>${status(key)}</span><p>${descriptions[key]}</p></div><button role="menuitem" data-role-command="toggle" ${last?'disabled':''}>${icon(roles[key].enabled?'runner':'plus')}<span>${roles[key].enabled?'关闭':'开启'} ${names[key]}</span></button>${last?'<p class="role-menu-hint">当前至少保留一个角色开启</p>':''}<div class="role-pop-separator"></div><button role="menuitem" data-role-command="settings">${icon('sliders')}<span>${names[key]} 设置</span>${icon('chevron')}</button>`;pop.hidden=false;button.setAttribute('aria-expanded','true');positionPop(button);pop.querySelector('button:not(:disabled)')?.focus()}
 const input=(label,key,value,hint='',type='text')=>`<label class="role-field"><span>${label}</span><input data-role-field="${key}" value="${escape(value)}" type="${type}" ${type==='number'?'min="1" max="64"':''}>${hint?`<small>${hint}</small>`:''}</label>`;
 const area=(label,key,value,hint)=>`<label class="role-field"><span>${label}</span><textarea data-role-field="${key}" rows="3">${escape(value)}</textarea><small>${hint}</small></label>`;
 function renderSettings(){const key=activeRole;const tabs=key==='agent'?[['main','工作空间'],['limits','执行限制']]:key==='gateway'?[['main','客户端接入'],['routes','路由与认证']]:[['main','公网入口'],['tls','TLS 与身份']];let content;
 if(key==='agent')content=roleTab==='main'?`${input('默认工作目录','cwd',draft.cwd,'调用未指定目录时使用。')}${area('允许访问的目录','allow',draft.allow,'每行一个目录。')}${area('保护目录','deny',draft.deny,'工具调用无法访问这些目录。')}`:`${input('同时执行的命令','exec',draft.exec,'并发上限，超额请求进入队列。','number')}${input('终端会话上限','pty',draft.pty,'控制本机 PTY 会话数量。','number')}<div class="role-related"><strong>工具授权</strong><p>按调用者与设备标签设置工具权限。</p><button data-role-command="authz" class="role-text-link">打开访问与授权 ${icon('arrow')}</button></div>`;
 else if(key==='gateway')content=roleTab==='main'?`${input('监听地址','listen',draft.listen,'默认仅监听本机地址。')}<div class="role-read-row"><span>客户端协议</span><strong>HTTP / MCP</strong></div><div class="role-read-row"><span>认证方式</span><strong>PAT 令牌</strong></div><div class="role-related"><strong>客户端连接</strong><p>在接入控制中复制连接地址、管理接单和查看连接状态。</p><button data-role-command="runtime" class="role-text-link">打开接入控制 ${icon('arrow')}</button></div>`:`<div class="role-info">已配对设备作为路由目标；每次调用保留目标设备与调用者信息。</div><div class="role-related"><strong>接入凭据</strong><p>在访问与授权中管理客户端令牌和授权范围。</p><button data-role-command="authz" class="role-text-link">管理令牌与授权 ${icon('arrow')}</button></div><div class="role-related"><strong>运行记录</strong><p>在会话页查看实时执行及历史审计。</p><button data-role-command="sessions" class="role-text-link">打开会话 ${icon('arrow')}</button></div>`;
 else content=roleTab==='main'?`<label class="role-field"><span>接入方式</span><select data-role-field="listen"><option value="tunnel" ${draft.listen==='tunnel'?'selected':''}>隧道</option><option value="public:443" ${draft.listen==='public:443'?'selected':''}>公网 HTTPS :443</option><option value="funnel" ${draft.listen==='funnel'?'selected':''}>Funnel</option></select><small>Funnel 需要本机 Tailnet 已连接。</small></label>${input('公开访问地址 / OAuth Issuer','issuer',draft.issuer,'使用 https:// 开头的完整来源地址。')}${input('公网域名','domain',draft.domain,'公网 HTTPS 模式下使用。')}<div class="role-info">保存配置后，可从顶部菜单开启 Ingress。</div>`:`<label class="role-field"><span>TLS 证书</span><select data-role-field="tls"><option value="autocert" ${draft.tls==='autocert'?'selected':''}>自动管理证书</option><option value="file" ${draft.tls==='file'?'selected':''}>指定证书文件</option></select></label>${draft.tls==='file'?input('证书文件','cert',draft.cert||'')+input('私钥文件','key',draft.key||''):''}<div class="role-related"><strong>OAuth 与公网访问</strong><p>客户端授权、访问限制与公网入口状态在对应模块中管理。</p><button data-role-command="ingress" class="role-text-link">打开公网入口 ${icon('arrow')}</button></div>`;
 dialog.innerHTML=`<div class="role-panel-head"><div><span>角色设置</span><h2 id="role-panel-title">${names[key]}</h2><p>${descriptions[key]}</p></div><button class="icon-button" data-role-command="close" aria-label="关闭角色设置">${icon('close')}</button></div><div class="role-state-banner"><i class="${roles[key].enabled?'on':''}"></i>${status(key)}<span>设置可独立编辑</span></div><div class="role-panel-tabs">${tabs.map(([id,label])=>`<button data-role-tab="${id}" class="${roleTab===id?'active':''}">${label}</button>`).join('')}</div><div class="role-panel-content">${content}</div><p class="role-error" id="role-error" aria-live="polite"></p><div class="role-panel-save"><span id="role-save-status">${dirty?'有未保存修改':'设置已保存'}</span><button class="button primary" data-role-command="review" ${dirty?'':'disabled'}>预览更改</button></div><p class="role-prototype">设计预览 · 设置与启停在页面内模拟</p>`;
 }
 function openSettings(key){activeRole=key;closePop();roleTab='main';draft=structuredClone(roles[key].settings);dirty=false;renderSettings();if(!dialog.open)dialog.showModal()}
 function closeDialog(){dialog.close();dialog.replaceChildren();pending=null;dirty=false;returnFocus?.focus()}
 function guardClose(){if(!dirty)return closeDialog();dialog.innerHTML=`<div class="role-panel-head"><div><span>待保存修改</span><h2 id="role-panel-title">离开 ${names[activeRole]} 设置？</h2></div></div><p class="role-info">这次编辑尚未保存。</p><div class="form-actions"><button class="button" data-role-command="continue">继续编辑</button><button class="button danger" data-role-command="discard">放弃修改并离开</button></div>`}
 function toggle(){closePop();if(activeRole==='ingress'&&!roles.ingress.enabled&&!roles.ingress.settings.issuer){openSettings('ingress');dialog.querySelector('#role-error').textContent='开启前请先配置公开访问地址。';return}const on=roles[activeRole].enabled;if(on&&Object.values(roles).filter(r=>r.enabled).length===1)return;pending={kind:'toggle',role:activeRole,on:!on};dialog.innerHTML=`<div class="role-panel-head"><div><span>角色管理</span><h2 id="role-panel-title">${on?'关闭':'开启'} ${names[activeRole]}</h2><p>${descriptions[activeRole]}</p></div><button class="icon-button" data-role-command="discard" aria-label="关闭">${icon('close')}</button></div><div class="role-info">${on?activeRole==='agent'?'将停止 Agent 接收新工具调用，并等待现有任务结束。':activeRole==='gateway'?'将停止客户端接入和新调用路由，现有连接可能中断。':'将停止公网接入，外部客户端需要等待入口重新开启。':activeRole==='ingress'?'将根据已保存的访问地址、TLS 和 OAuth 配置开启公网入口。':'将按已保存配置启动此角色。'}</div><div class="role-read-row"><span>变更角色</span><strong>${names[activeRole]}</strong></div><div class="role-read-row"><span>目标状态</span><strong>${on?'已关闭':'已开启'}</strong></div><p class="role-prototype">演示状态变更；正式应用按内核返回判断热更新或重启。</p><div class="form-actions"><button class="button quiet" data-role-command="discard">取消</button><button class="button primary" data-role-command="confirm-toggle">${on&&activeRole==='agent'?'等待任务完成并关闭':'确认'+(on?'关闭':'开启')}</button></div>`;if(!dialog.open)dialog.showModal()}
 function review(){if(activeRole==='agent'&&(!draft.cwd.trim()||![draft.exec,draft.pty].every(x=>Number.isInteger(Number(x))&&Number(x)>0))){dialog.querySelector('#role-error').textContent='请检查工作目录和执行限制。';return}if(activeRole==='gateway'&&!/^[\w.:-]+:\d+$/.test(draft.listen)){dialog.querySelector('#role-error').textContent='请输入包含端口的监听地址。';return}if(activeRole==='ingress'&&(!/^https:\/\/[^/\s]+$/.test(draft.issuer)||draft.listen==='public:443'&&!draft.domain||draft.tls==='file'&&(!draft.cert||!draft.key))){dialog.querySelector('#role-error').textContent='请检查 HTTPS 访问地址、域名和证书配置。';return}const diffs=Object.entries(draft).filter(([k,v])=>v!==roles[activeRole].settings[k]);pending={kind:'save',role:activeRole,settings:structuredClone(draft)};dialog.innerHTML=`<div class="role-panel-head"><div><span>设置预览</span><h2 id="role-panel-title">${names[activeRole]} 配置更改</h2></div></div><div class="role-review-list">${diffs.map(([k,v])=>`<div><strong>${escape(k)}</strong><span>${escape(roles[activeRole].settings[k]||'未设置')}</span><b>→</b><code>${escape(v)}</code></div>`).join('')}</div><p class="role-info">仅更新当前模块的设置。启停状态由顶部菜单控制。</p><div class="form-actions"><button class="button" data-role-command="continue">返回编辑</button><button class="button primary" data-role-command="save">确认保存</button></div>`}
 host.addEventListener('click',e=>{const b=e.target.closest('[data-role-trigger]');if(b)openPop(b.dataset.roleTrigger,b)});
 pop.addEventListener('click',e=>{const command=e.target.closest('[data-role-command]')?.dataset.roleCommand;if(command==='toggle')toggle();if(command==='settings')openSettings(activeRole)});
 dialog.addEventListener('input',e=>{if(!e.target.dataset.roleField)return;draft[e.target.dataset.roleField]=e.target.value;dirty=JSON.stringify(draft)!==JSON.stringify(roles[activeRole].settings);dialog.querySelector('#role-save-status').textContent=dirty?'有未保存修改':'设置已保存';dialog.querySelector('[data-role-command="review"]').disabled=!dirty});
 dialog.addEventListener('change',e=>{if(e.target.dataset.roleField==='tls'){draft.tls=e.target.value;dirty=true;renderSettings()}});
 dialog.addEventListener('click',e=>{const tab=e.target.closest('[data-role-tab]');if(tab){roleTab=tab.dataset.roleTab;renderSettings();return}const command=e.target.closest('[data-role-command]')?.dataset.roleCommand;if(command==='close')guardClose();if(command==='discard')closeDialog();if(command==='continue')renderSettings();if(command==='review')review();if(command==='save'&&pending){roles[pending.role].settings=pending.settings;save();closeDialog();window.dispatchEvent(new Event('xmesh-role-preview-change'));if(typeof notify==='function')notify('演示：模块设置已保存')}if(command==='confirm-toggle'&&pending){roles[pending.role].enabled=pending.on;save();renderButtons();closeDialog();window.dispatchEvent(new Event('xmesh-role-preview-change'));if(typeof notify==='function')notify('演示：角色状态已更新')}if(['authz','runtime','ingress','sessions'].includes(command)){if(dirty){guardClose();return}closeDialog();document.querySelector(`[data-nav-id="${command}"]`)?.click()}});
 dialog.addEventListener('cancel',e=>{e.preventDefault();guardClose()});
 document.addEventListener('pointerdown',e=>{if(!pop.hidden&&!pop.contains(e.target)&&!host.contains(e.target))closePop()});
 document.addEventListener('keydown',e=>{if(pop.hidden)return;if(e.key==='Escape'){e.preventDefault();closePop();returnFocus?.focus()}if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const buttons=[...pop.querySelectorAll('button:not(:disabled)')],current=buttons.indexOf(document.activeElement);buttons[(current+(e.key==='ArrowDown'?1:buttons.length-1))%buttons.length]?.focus()}});
 window.addEventListener('resize',()=>{if(!pop.hidden&&returnFocus)positionPop(returnFocus)});

 const nodeDialog=document.createElement('dialog');nodeDialog.className='node-settings-dialog';nodeDialog.setAttribute('aria-labelledby','node-panel-title');document.body.append(nodeDialog);
 let nodeData={name:'xiaosong-mac',mode:'coexist'},nodeDraft=null;
 function openNode(){nodeDraft={...nodeData};nodeDialog.innerHTML=`<div class="role-panel-head"><div><span>本机设置</span><h2 id="node-panel-title">设备与网络</h2></div><button class="icon-button" data-node-command="close" aria-label="关闭本机设置">${icon('close')}</button></div><label class="role-field"><span>设备名称</span><input id="node-name-preview" value="${escape(nodeDraft.name)}"><small>使用小写字母、数字和连字符。</small></label><label class="role-field"><span>联网方式</span><select id="node-mode-preview"><option value="lan" ${nodeDraft.mode==='lan'?'selected':''}>局域网</option><option value="tailnet" ${nodeDraft.mode==='tailnet'?'selected':''}>Tailnet</option><option value="coexist" ${nodeDraft.mode==='coexist'?'selected':''}>局域网与 Tailnet</option><option value="offline" ${nodeDraft.mode==='offline'?'selected':''}>暂不联网</option></select><small>控制面凭据、网络策略和中继在 Tailnet 模块中管理。</small></label><p class="role-info">修改联网方式会影响设备间的连接路径。</p><p id="node-error-preview" class="role-error"></p><div class="form-actions"><button class="button" data-node-command="close">取消</button><button class="button primary" data-node-command="review">预览更改</button></div><p class="role-prototype">设计预览 · 此操作仅更新当前页面</p>`;nodeDialog.showModal()}
 nodeDialog.addEventListener('click',e=>{const command=e.target.closest('[data-node-command]')?.dataset.nodeCommand;if(command==='close')nodeDialog.close();if(command==='review'){nodeDraft={name:nodeDialog.querySelector('#node-name-preview').value.trim(),mode:nodeDialog.querySelector('#node-mode-preview').value};if(!/^[a-z0-9][a-z0-9-]{0,62}$/.test(nodeDraft.name)){nodeDialog.querySelector('#node-error-preview').textContent='请检查设备名称。';return}nodeDialog.innerHTML=`<div class="role-panel-head"><div><span>设备设置</span><h2 id="node-panel-title">确认本机配置</h2></div></div><div class="role-read-row"><span>设备名称</span><strong>${escape(nodeDraft.name)}</strong></div><div class="role-read-row"><span>联网方式</span><strong>${{lan:'局域网',tailnet:'Tailnet',coexist:'局域网与 Tailnet',offline:'暂不联网'}[nodeDraft.mode]}</strong></div><div class="form-actions"><button class="button" data-node-command="close">取消</button><button class="button primary" data-node-command="save">确认保存</button></div>`}if(command==='save'){nodeData={...nodeDraft};nodeDialog.close();if(typeof notify==='function')notify('演示：本机配置已保存')}});
 const local=document.querySelector('.local-device');if(local){const trigger=document.createElement('button');trigger.className='icon-button node-setting-trigger';trigger.setAttribute('aria-label','本机设备设置');trigger.title='本机设备设置';trigger.innerHTML=icon('sliders');local.append(trigger);trigger.addEventListener('click',openNode)}
 window.xmeshRolePreview={open:openSettings,get:()=>structuredClone(roles)};
 renderButtons();
})();
